mapper.insert:

    SELECT SEQ_EMAIL_INVITATION.NEXTVAL FROM DUAL

INSERT INTO EMAIL_INVITATION (
    INVITATION_NUM, TEAM_NUM, INVITER_NUM, INVITEE_EMAIL, STATUS, SENT_AT, EXPIRED_AT
) VALUES (
    #{invitation_num}, #{team_num}, #{inviter_num}, #{invitee_email}, 1, SYSDATE, SYSDATE + 3
)

mapper.select:
SELECT * FROM (
    SELECT INVITATION_NUM, TEAM_NUM, INVITER_NUM, INVITEE_EMAIL, STATUS, SENT_AT, RESPONSED_AT, EXPIRED_AT
    FROM EMAIL_INVITATION
    WHERE TEAM_NUM = #{teamNum}
      AND INVITEE_EMAIL = #{email}
    ORDER BY SENT_AT DESC
)
WHERE ROWNUM = 1

SELECT INVITATION_NUM, TEAM_NUM, INVITER_NUM, INVITEE_EMAIL, STATUS, SENT_AT, RESPONSED_AT, EXPIRED_AT
FROM EMAIL_INVITATION
WHERE INVITATION_NUM = #{invitationNum}

mapper.update:
UPDATE EMAIL_INVITATION
SET STATUS = #{status}
WHERE INVITATION_NUM = #{invitationNum}
